// VALIDACION DE DATOS DEL ESP32 + EXTRACCION IP PUBLICA
const input = $input.first().json;
const datos = input.body || input.data || input;
const headers = input.headers || {};

const camposRequeridos = ['temp', 'hum', 'luz', 'presencia'];
const camposFaltantes = camposRequeridos.filter(c => datos[c] === undefined);
if (camposFaltantes.length > 0) {
  throw new Error(`Campos faltantes: ${camposFaltantes.join(', ')}`);
}

let errores = [];
if (datos.temp !== -999 && (datos.temp < -20 || datos.temp > 60)) errores.push(`Temperatura fuera de rango: ${datos.temp}`);
if (datos.hum !== -999 && (datos.hum < 0 || datos.hum > 100)) errores.push(`Humedad fuera de rango: ${datos.hum}`);

// IP publica real del cliente (X-Forwarded-For lo llena el proxy de progian8n)
const publicIp = (headers['x-forwarded-for'] || '').split(',')[0].trim() || headers['x-real-ip'] || '';

const staticData = $getWorkflowStaticData('global');
const lat = staticData.lat || null;
const lon = staticData.lon || null;
const ciudad = staticData.ciudad || 'Sin configurar';

return [{
  json: {
    temp_interior: datos.temp,
    humedad_interior: datos.hum,
    luz: datos.luz,
    presencia: datos.presencia,
    distancia: datos.distancia || -1,
    sensor_valido: datos.valido !== false,
    ip_esp32: datos.ip || 'desconocida',
    ip_publica: publicIp,
    rssi: datos.rssi || 0,
    uptime: datos.uptime || 0,
    lat: lat,
    lon: lon,
    ciudad: ciudad,
    tiene_ubicacion: lat !== null && lon !== null,
    timestamp: new Date().toISOString(),
    errores_validacion: errores
  }
}];

// AUTO-LOCALIZACION POR IP: solo se usa si no habia staticData
const datos = $('2. Validar Datos Sensor').first().json;
const ipData = $input.first().json;

// Si ya tenia ubicacion (staticData configurada), no tocamos nada
if (datos.tiene_ubicacion) {
  return [{ json: { ...datos, origen_ubicacion: 'staticData (manual)' } }];
}

// Si la llamada a ip-api funciono, usar esos datos
if (ipData && ipData.status === 'success' && ipData.lat && ipData.lon) {
  // Guardar en staticData para futuras ejecuciones
  const staticData = $getWorkflowStaticData('global');
  staticData.lat = ipData.lat;
  staticData.lon = ipData.lon;
  staticData.ciudad = ipData.city || 'Desconocida';
  staticData.origen = 'ip-api (auto)';
  staticData.actualizado = new Date().toISOString();

  return [{
    json: {
      ...datos,
      lat: ipData.lat,
      lon: ipData.lon,
      ciudad: ipData.city,
      tiene_ubicacion: true,
      origen_ubicacion: 'ip-api (auto)'
    }
  }];
}

// IP lookup fallo: pasamos sin ubicacion (ira por la rama 5b)
return [{ json: { ...datos, origen_ubicacion: 'ninguna' } }];

// COMBINAR INTERIOR + EXTERIOR + DETECTAR ANOMALIAS
const sensor = $('3. Tiene Ubicacion?').first().json;
const meteo = $input.first().json;
const current = meteo.current || {};

const temp_ext = current.temperature_2m || null;
const hum_ext = current.relative_humidity_2m || null;

const diff_temp = (sensor.temp_interior !== -999 && temp_ext !== null) 
  ? Math.round((sensor.temp_interior - temp_ext) * 10) / 10 : null;

let anomalias = [];
if (sensor.temp_interior > 30) anomalias.push('Temp interior alta');
if (sensor.temp_interior < 15) anomalias.push('Temp interior baja');
if (sensor.humedad_interior > 70) anomalias.push('Humedad interior alta');
if (sensor.humedad_interior < 25) anomalias.push('Humedad interior baja');
if (sensor.luz < 20 && sensor.presencia) anomalias.push('Poca luz con presencia');
if (diff_temp !== null && Math.abs(diff_temp) > 8) anomalias.push('Gran diferencia interior/exterior');
if ((current.uv_index || 0) >= 8) anomalias.push('Indice UV alto exterior');
if (!sensor.sensor_valido) anomalias.push('Error lectura DHT11');

return [{
  json: {
    ...sensor,
    temp_exterior: temp_ext,
    hum_exterior: hum_ext,
    viento: current.wind_speed_10m || null,
    uv: current.uv_index || null,
    diff_temp: diff_temp,
    anomalias: anomalias,
    hay_anomalia: anomalias.length > 0
  }
}];

// SIN UBICACION - Solo sensor
const sensor = $input.first().json;

let anomalias = [];
if (sensor.temp_interior > 30) anomalias.push('Temp interior alta');
if (sensor.temp_interior < 15) anomalias.push('Temp interior baja');
if (sensor.humedad_interior > 70) anomalias.push('Humedad interior alta');
if (sensor.humedad_interior < 25) anomalias.push('Humedad interior baja');
if (sensor.luz < 20 && sensor.presencia) anomalias.push('Poca luz con presencia');

return [{
  json: {
    ...sensor,
    temp_exterior: null,
    hum_exterior: null,
    viento: null,
    uv: null,
    diff_temp: null,
    anomalias: anomalias,
    hay_anomalia: anomalias.length > 0
  }
}];

