// PARSEAR RESPUESTA IA Y PREPARAR MENSAJE
const respuestaLLM = $input.first().json;

let datosAnteriores;
try { datosAnteriores = $('5. Combinar Interior + Exterior').first().json; }
catch(e) { datosAnteriores = $('5b. Sin Ubicacion (solo sensor)').first().json || {}; }

let analisis = 'Sin respuesta IA';
let nivel = 'AMARILLO';

try {
  analisis = respuestaLLM.choices[0].message.content;
  if (analisis.includes('ROJO')) nivel = 'ROJO';
  else if (analisis.includes('AMARILLO')) nivel = 'AMARILLO';
  else if (analisis.includes('VERDE')) nivel = 'VERDE';
} catch (e) { analisis = 'Error IA: ' + e.message; }

const d = datosAnteriores;
const mensaje = `ESTACION IoT - ${d.ciudad || 'Sin ubicacion'}\n\nInterior:\nTemp: ${d.temp_interior}C  Hum: ${d.humedad_interior}%\nLuz: ${d.luz}%  Presencia: ${d.presencia ? 'Si' : 'No'}\n\nExterior:\nTemp: ${d.temp_exterior || 'N/A'}C  Hum: ${d.hum_exterior || 'N/A'}%\nViento: ${d.viento || 'N/A'} km/h  UV: ${d.uv || 'N/A'}\n\nAnalisis IA:\n${analisis}\n\nNivel: ${nivel}`;

return [{
  json: {
    ...d,
    analisis_ia: analisis,
    nivel_alerta: nivel,
    mensaje_telegram: mensaje
  }
}];

// GUARDAR UBICACION DESDE WEB
const input = $input.first().json;
const datos = input.body || input;

const staticData = $getWorkflowStaticData('global');
staticData.lat = datos.lat;
staticData.lon = datos.lon;
staticData.ciudad = datos.ciudad || 'Desconocida';
staticData.actualizado = new Date().toISOString();

return [{
  json: {
    ok: true,
    ciudad: staticData.ciudad,
    lat: staticData.lat,
    lon: staticData.lon
  }
}];

// CLASIFICAR MENSAJE Y PROCESAR CASOS SIMPLES (location / comando) INLINE
// Tipos: 'text' (sigue a rama embeddings), 'direct' (ya tengo respuesta lista)
const input = $input.first().json;
const datos = input.body || input;
const message = datos.message;

if (!message) {
  return [{ json: { tipo: 'direct', chatId: null, respuesta: 'Sin mensaje' }}];
}

const chatId = message.chat?.id;
const fromName = message.from?.first_name || 'Usuario';

// 1) Ubicacion compartida por Telegram → guardar y responder
if (message.location) {
  const staticData = $getWorkflowStaticData('global');
  staticData.lat = message.location.latitude;
  staticData.lon = message.location.longitude;
  staticData.actualizado = new Date().toISOString();
  // Nota: la ciudad se actualiza con reverse geocoding en otro proceso o queda pendiente
  staticData.ciudad = staticData.ciudad || 'Pendiente geocoding';

  return [{ json: {
    tipo: 'direct',
    chatId,
    respuesta: `Ubicacion actualizada: lat=${message.location.latitude.toFixed(4)} lon=${message.location.longitude.toFixed(4)}. Usare estos datos para las predicciones.`
  }}];
}

const texto = (message.text || '').trim();

// 2) Comandos
if (texto === '/start' || texto === '/help') {
  return [{ json: {
    tipo: 'direct',
    chatId,
    respuesta: `Hola ${fromName}. Soy el asistente de tu Estacion IoT.\n\n- Preguntame sobre el historico (ej: cuando tuve la humedad mas alta?).\n- Comparte tu ubicacion para actualizar la ciudad.\n- /help para ver esta ayuda.`
  }}];
}

// 3) Texto = pregunta para el chatbot con embeddings
if (texto.length > 0) {
  return [{ json: {
    tipo: 'text',
    chatId,
    fromName,
    pregunta: texto
  }}];
}

// 4) Otro tipo: ignorar silenciosamente
return [{ json: { tipo: 'direct', chatId, respuesta: 'Tipo de mensaje no soportado. Envia texto o tu ubicacion.' }}];

// Construir prompt con historico + pregunta
// El embedding de la pregunta esta ya calculado. Lo mencionamos en meta.
const embeddingRes = $input.first().json;
const histRes = $('CHAT 4. Leer historico Sheets').first().json;
const clasif = $('CHAT 2. Clasificar').first().json;

const rows = histRes.rows || [];
const historico = rows.map((r, i) => 
  `${i+1}. ${r.Timestamp} | ${r.Ciudad || 'N/A'} | Int T=${r.Temp_Interior}C H=${r.Humedad}% Luz=${r.Luz}% Pres=${r.Presencia} | Ext T=${r.Temp_Exterior}C H=${r.Hum_Exterior}% Viento=${r.Viento}km/h UV=${r.UV} | Alerta=${r.Alerta_IA}`
).join('\n');

const prompt = `Historico de la estacion IoT (${rows.length} lecturas):\n${historico}\n\nPregunta: ${clasif.pregunta}\n\nResponde en espanol, conciso (max 4 frases), citando datos cuando sea relevante.`;

const embDim = (embeddingRes.embedding?.values || []).length;

return [{
  json: {
    chatId: clasif.chatId,
    prompt,
    embeddingDim: embDim,
    modelo_embedding: 'text-embedding-004'
  }
}];

// OBTENER UBICACION REAL ACTUAL
// Prioridad:
// 1. staticData (lo ultimo que el usuario envio via web o Telegram → ubicacion REAL)
// 2. Si no hay, pedir al usuario que configure la ubicacion

const staticData = $getWorkflowStaticData('global');

if (!staticData.lat || !staticData.lon) {
  throw new Error('Sin ubicacion configurada. Comparte tu ubicacion al bot de Telegram o usa la mini web de geolocalizacion antes de ejecutar la prediccion.');
}

let ciudad = (staticData.ciudad || '').trim();
// Anadir pais si la ciudad no lo incluye, para evitar ambiguedad con la LLM
if (ciudad && !ciudad.includes(',')) {
  ciudad = ciudad + ', Espana';
}
if (!ciudad) ciudad = `lat=${staticData.lat}, lon=${staticData.lon}`;

return [{
  json: {
    lat: staticData.lat,
    lon: staticData.lon,
    ciudad: ciudad,
    ciudadCorta: staticData.ciudad || 'Sin nombre',
    origen: staticData.origen || 'web/telegram',
    actualizado: staticData.actualizado
  }
}];

// Construir prompt de prediccion
const forecast = $input.first().json;
const ubic = $('FCST 2. Ubicacion real (staticData)').first().json;
const hourly = forecast.hourly || {};
const times = hourly.time || [];
const temps = hourly.temperature_2m || [];
const hums = hourly.relative_humidity_2m || [];
const precs = hourly.precipitation_probability || [];
const uvs = hourly.uv_index || [];

const resumen = times.slice(0, 24).filter((_, i) => i % 3 === 0).map((t, idx) => {
  const i = idx * 3;
  const hora = t.slice(11, 16);
  return `${hora}: ${temps[i]}C, Hum ${hums[i]}%, Lluvia ${precs[i] || 0}%, UV ${uvs[i] || 0}`;
}).join('\n');

const fechaHoy = new Date().toISOString().slice(0, 10);
const prompt = `Eres un asistente IoT. Genera una prediccion breve (max 4 frases) para hoy ${fechaHoy} en ${ubic.ciudad}.\n\nCoordenadas reales: lat=${ubic.lat}, lon=${ubic.lon}\n\nPronostico 24h (cada 3h):\n${resumen}\n\nDestaca: maxima/minima, lluvia, UV, recomendacion practica. Empieza con el dia y la ciudad. NO inventes datos que no esten en el pronostico. NO confundas la ciudad con otra homonima en otro pais.`;

return [{ json: { prompt, ciudad: ubic.ciudad, ciudadCorta: ubic.ciudadCorta }}];
